"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[23626],{23626:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/twelve-footsteps.png\\"\\n          title=\\"Twelve Footsteps\\"\\n          author=\\"Jeong Jae-seung\\"\\n          publisher=\\"Across\\"\\n          publishedDate=\\"2018-07-02\\"\\n          isbn=\\"9791160560510\\"\\n          rating=4.5\\n          tags=\\"science\\"\\n        />\\n</center>\\n\\n## Review\\nIf you like ```brain science```, this is a special lecture you must never miss.  \\nRecently, my interest shifted from psychology to brain science.  \\nI thought that to understand human psychology more deeply, I should know about the more fundamental ```brain```.  \\nPerhaps that\'s why I could read this book more enjoyably and interestingly.  \\n<br>\\nThis book makes the reader ask \'why?\' about things they took for granted and look at the familiar world and phenomena from a new perspective.  \\nI think it is an excellent popular science book that allows one to look into the human heart with the microscope of <mark>brain science</mark> and view society and the future with the telescope of complex systems science.  "}')}}]);